}

.flow-character-stage::after{
  content:"";
  position:absolute;
  right:-68px;
  bottom:-28px;
  width:220px;
  height:220px;
  border-radius:50%;
  background:radial-gradient(circle, rgba(119,168,61,.12) 0%, rgba(119,168,61,.05) 52%, transparent 72%);
